"use client"

import { useState, useEffect } from "react"
import { Button } from "@/components/ui/button"
import { ArrowRight, Sparkles } from "lucide-react"

const codeLines = [
  '// Auto-generated by SL Builder AI',
  '// Hover Glow Effect - Touch Activated',
  '',
  'float glow_intensity = 0.4;',
  'vector glow_color = <0.2, 1.0, 0.6>;',
  '',
  'default',
  '{',
  '    state_entry()',
  '    {',
  '        llSetText("Touch to activate", glow_color, 1.0);',
  '    }',
  '',
  '    touch_start(integer num)',
  '    {',
  '        llSetPrimitiveParams([',
  '            PRIM_GLOW, ALL_SIDES, glow_intensity,',
  '            PRIM_COLOR, ALL_SIDES, glow_color, 1.0,',
  '            PRIM_POINT_LIGHT, TRUE, glow_color, 1.0, 10.0, 0.5',
  '        ]);',
  '        llSay(0, "Glow activated!");',
  '    }',
  '}',
]

export function Hero() {
  const [visibleLines, setVisibleLines] = useState(0)

  useEffect(() => {
    if (visibleLines < codeLines.length) {
      const timer = setTimeout(() => {
        setVisibleLines((prev) => prev + 1)
      }, 120)
      return () => clearTimeout(timer)
    }
  }, [visibleLines])

  return (
    <section className="relative flex flex-col items-center justify-center px-6 pt-32 pb-20 text-center lg:pt-44 lg:pb-32">
      {/* Glow effect */}
      <div className="pointer-events-none absolute top-0 left-1/2 -z-10 h-[600px] w-[800px] -translate-x-1/2 rounded-full bg-primary/5 blur-3xl" />

      <div className="mb-6 inline-flex items-center gap-2 rounded-full border border-border bg-secondary px-4 py-1.5 text-sm text-muted-foreground">
        <Sparkles className="h-3.5 w-3.5 text-primary" />
        <span>AI-Powered Virtual World Creation</span>
      </div>

      <h1 className="max-w-4xl text-balance text-4xl font-bold tracking-tight text-foreground sm:text-5xl lg:text-7xl">
        Build Virtual Worlds with{" "}
        <span className="text-transparent bg-clip-text bg-gradient-to-r from-primary via-accent to-primary animate-gradient-text">
          Intelligent Scripts
        </span>
      </h1>

      <p className="mt-6 max-w-2xl text-pretty text-lg leading-relaxed text-muted-foreground lg:text-xl">
        Generate production-ready LSL scripts, prefab layouts, NPC systems,
        world plans, and texture concepts for virtual worlds. Describe what you want, and get
        copy-paste ready code in seconds.
      </p>

      <div className="mt-10 flex flex-col items-center gap-4 sm:flex-row">
        <Button size="lg" className="gap-2 px-8 text-base font-semibold" asChild>
          <a href="#generator">
            Start Building
            <ArrowRight className="h-4 w-4" />
          </a>
        </Button>
        <Button
          variant="outline"
          size="lg"
          className="gap-2 px-8 text-base"
          asChild
        >
          <a href="#features">Explore Features</a>
        </Button>
      </div>

      {/* Code preview with typing effect */}
      <div className="mt-16 w-full max-w-3xl overflow-hidden rounded-xl border border-border bg-card shadow-2xl shadow-primary/5">
        <div className="flex items-center gap-2 border-b border-border bg-secondary/50 px-4 py-3">
          <div className="h-3 w-3 rounded-full bg-destructive/60" />
          <div className="h-3 w-3 rounded-full bg-chart-4/60" />
          <div className="h-3 w-3 rounded-full bg-primary/60" />
          <span className="ml-3 font-mono text-xs text-muted-foreground">
            hover_glow.lsl
          </span>
        </div>
        <pre className="overflow-x-auto p-6 text-left font-mono text-sm leading-relaxed text-foreground/80">
          <code>
            {codeLines.slice(0, visibleLines).map((line, i) => (
              <span key={i} className="block animate-in fade-in duration-200">
                {line}
              </span>
            ))}
            {visibleLines < codeLines.length && (
              <span className="typing-cursor" />
            )}
          </code>
        </pre>
      </div>
    </section>
  )
}
